import ast
import sys

def find_unused_code(filepath):
    with open(filepath, 'r') as f:
        content = f.read()

    # Look for patterns that might indicate dead code
    lines = content.split('\\n')

    print('Checking for potential dead code patterns...')

    # Check for unused imports
    tree = ast.parse(content)

    # Get all names defined in the module
    defined_names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            defined_names.add(node.name)
        elif isinstance(node, ast.ClassDef):
            defined_names.add(node.name)
        elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            defined_names.add(node.id)

    # Check for imports that might not be used
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name not in defined_names:
                    # Check if it's used anywhere
                    used = False
                    for n in ast.walk(tree):
                        if isinstance(n, ast.Name) and n.id == alias.name:
                            used = True
                            break
                    if not used and alias.name not in ['typing', 'typing_extensions']:
                        print(f'Potential unused import: {alias.name} at line {node.lineno}')

    # Look for empty except blocks
    for i, line in enumerate(lines):
        if 'except:' in line or 'except Exception:' in line or 'except BaseException:' in line:
            # Check next few lines for just 'pass'
            for j in range(i+1, min(i+5, len(lines))):
                if 'pass' in lines[j].strip() and not lines[j].strip().startswith('#'):
                    print(f'Empty except block at line {i+1}: {line.strip()}')
                    break

