import ast
import sys

def analyze_file(filepath):
    with open(filepath, 'r') as f:
        content = f.read()

    tree = ast.parse(content)

    # Collect all names used in the file
    used_names = set()
    defined_names = set()

    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            used_names.add(node.id)
        elif isinstance(node, ast.FunctionDef):
            defined_names.add(node.name)
        elif isinstance(node, ast.ClassDef):
            defined_names.add(node.name)
        elif isinstance(node, ast.Attribute):
            # For attribute access like module.name
            if isinstance(node.value, ast.Name):
                used_names.add(node.value.id)

    # Check imports
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                print(f'Import: {alias.name} as {alias.asname or alias.name}')
                # Check if imported name is used
                name_to_check = alias.asname or alias.name
                if name_to_check not in used_names and name_to_check not in defined_names:
                    print(f'  WARNING: {name_to_check} may not be used')
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ''
            for alias in node.names:
                full_name = f'{module}.{alias.name}' if module else alias.name
                print(f'Import from: {full_name} as {alias.asname or alias.name}')
                name_to_check = alias.asname or alias.name
                if name_to_check not in used_names and name_to_check not in defined_names:
